cd /bot/src && timeout 40 python3 <<'EOF'
import json
rows=[]
for l in open('/tmp/lap.jsonl'):
    try: rows.append(json.loads(l))
    except: pass
tot=0; neg=0; ctx={}
for r in rows:
    L=r[3:]
    for i,v in enumerate(L):
        tot+=1
        if v<0:
            neg+=1
            nb=[L[(i+k)%16] for k in (-1,1)]
            m=max(nb)
            ctx[round(m,1)]=ctx.get(round(m,1),0)+1
print("neg fraction", neg/tot, neg, tot)
print("neighbor-max hist:", dict(sorted(ctx.items())))
